from itertools import product, combinations
from collections import Counter
import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        if name_order == "descending":
            names.reverse()
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[None] + list(packages[name]) for name in names]
        best_key = None
        best_versions = None

        for assignment in product(*choices):
            selected = {name: row for name, row in zip(names, assignment) if row is not None}
            valid = True
            for name, bounds in data["roots"].items():
                row = selected.get(name)
                if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            reached = set()
            edges = {}
            pending = list(data["roots"])
            while pending and valid:
                name = pending.pop()
                if name in reached:
                    continue
                reached.add(name)
                row = selected.get(name)
                if row is None:
                    valid = False
                    break
                version = row["version"]
                if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                    valid = False
                    break
                active = [dep for dep in row.get("deps", [])
                          if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in active:
                    other = dep["name"]
                    child = selected.get(other)
                    if child is None or not dep["min"] <= child["version"] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                    pending.append(other)
            if not valid or reached != set(selected):
                continue

            finished, active_nodes = set(), set()
            def visit(node):
                if node in active_nodes:
                    return False
                if node in finished:
                    return True
                active_nodes.add(node)
                if any(not visit(child) for child in edges.get(node, [])):
                    return False
                active_nodes.remove(node)
                finished.add(node)
                return True
            if not all(visit(node) for node in edges):
                continue

            vector = tuple(selected[n]["version"] if n in selected else -1 for n in names)
            if best_key is None or (vector < best_key if preference == "minimum" else vector > best_key):
                best_key = vector
                best_versions = {n: row["version"] for n, row in selected.items()}
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_01():
    return _dependency_solver("minimum", "ascending")

def _build_component_02():
    return _dependency_solver("maximum", "descending")

def _build_component_03():
    return _dependency_solver("minimum", "descending")

def _build_component_04():
    return _dependency_solver("maximum", "ascending")

def _build_component_05():
    return _dependency_solver("minimum", "ascending")


def _build_component_06():
    def rounded(n, denominator, mode):
        if mode == "half_up":
            return (n + denominator // 2) // denominator
        return n // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            ident = event.get("id", "anonymous:" + str(pos))
            key = (sequence, event.get("revision", 0), pos)
            if ident not in winners or key > winners[ident][0]:
                winners[ident] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            mode = data["rounding"]
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if len(mandatory) > k:
            return {"error": "impossible"}
        best_ids = None
        best_value = None
        for subset in combinations(jobs, k):
            ids = {j["id"] for j in subset}
            if not mandatory.issubset(ids):
                continue
            counts = Counter(j["group"] for j in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            selected = sorted(ids)
            value = sum(j["value"] for j in subset)
            if best_value is None or value > best_value or (value == best_value and selected < best_ids):
                best_value, best_ids = value, selected
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit.get(data["source"], 0)
        start_state = (data["source"], initial_mask, data["coupons"])
        dist = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [edge["duration"]]
                if remaining:
                    durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
                for index, duration in enumerate(durations):
                    left = remaining - (1 if index == 1 else 0)
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, left)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival,) + next_state)
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
